
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_mpw1pw_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_mpw1pw", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.313697816360488e+00, -3.251428188741140e+00, -3.164207038897509e+00, -3.043454888272831e+00, -2.879064261809507e+00, -2.660588282833101e+00, -2.380045697003499e+00, -2.036940507655759e+00, -1.644854407308474e+00, -1.234287798668175e+00, -8.377253246811732e-01, -5.735298491865133e-01, -4.996276079936622e-01, -4.112067050786418e-01, -2.967944640877608e-01, -1.889385826351623e-01, -1.088248788315423e-01, -3.694628556833648e-02, -9.454876107126439e-04, -2.361594564686073e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


